module HtmlToMarkdown
  # Result of a visitor callback.
  #
  # Allows visitors to control the conversion flow by either proceeding
  # with default behavior, providing custom output, skipping elements,
  # preserving HTML, or signaling errors.
  module VisitResult
    extend T::Helpers
    extend T::Sig

    interface!

    # Dispatch from a Hash to the appropriate variant constructor.
    # @param hash [Hash] with discriminator field and variant-specific fields
    # @return [variant_class] an instance of the appropriate variant
    sig { params(hash: T::Hash[T.untyped, T.untyped]).returns(T.untyped) }
    def self.from_hash(hash)
      discriminator = hash[:type] || hash["type"]
      case discriminator
      when "continue"
        VisitResultContinue.from_hash(hash)
      when "custom"
        VisitResultCustom.from_hash(hash)
      when "skip"
        VisitResultSkip.from_hash(hash)
      when "preserve_html"
        VisitResultPreserveHtml.from_hash(hash)
      when "error"
        VisitResultError.from_hash(hash)
      else
        raise "Unknown discriminator: #{discriminator}"
      end
    end
  end
  ## Continue with default conversion behavior
  VisitResultContinue = Data.define do
    include VisitResult
    extend T::Sig

    sig { returns(T::Boolean) }
    def continue? = true
    sig { returns(T::Boolean) }
    def custom? = false
    sig { returns(T::Boolean) }
    def skip? = false
    sig { returns(T::Boolean) }
    def preserve_html? = false
    sig { returns(T::Boolean) }
    def error? = false
    # @param hash [Hash] deserialized from the native extension
    # @return [self]
    sig { params(hash: T::Hash[T.untyped, T.untyped]).returns(T.attached_class) }
    def self.from_hash(hash)
      new
    end
  end
  ## Replace default output with custom markdown
  ##
  ## The visitor takes full responsibility for the markdown output
  ## of this node and its children.
  VisitResultCustom = Data.define(:value) do
    include VisitResult
    extend T::Sig

    # @return [String]
    sig { returns(String) }
    def value = Data.instance_method(:to_h).bind_call(self).fetch(:value)
    sig { returns(T::Boolean) }
    def continue? = false
    sig { returns(T::Boolean) }
    def custom? = true
    sig { returns(T::Boolean) }
    def skip? = false
    sig { returns(T::Boolean) }
    def preserve_html? = false
    sig { returns(T::Boolean) }
    def error? = false
    # @param hash [Hash] deserialized from the native extension
    # @return [self]
    sig { params(hash: T::Hash[T.untyped, T.untyped]).returns(T.attached_class) }
    def self.from_hash(hash)
      new(value: hash[:output] || hash["output"])
    end
  end
  ## Skip this element entirely (don't output anything)
  ##
  ## The element and all its children are ignored in the output.
  VisitResultSkip = Data.define do
    include VisitResult
    extend T::Sig

    sig { returns(T::Boolean) }
    def continue? = false
    sig { returns(T::Boolean) }
    def custom? = false
    sig { returns(T::Boolean) }
    def skip? = true
    sig { returns(T::Boolean) }
    def preserve_html? = false
    sig { returns(T::Boolean) }
    def error? = false
    # @param hash [Hash] deserialized from the native extension
    # @return [self]
    sig { params(hash: T::Hash[T.untyped, T.untyped]).returns(T.attached_class) }
    def self.from_hash(hash)
      new
    end
  end
  ## Preserve original HTML (don't convert to markdown)
  ##
  ## The element's raw HTML is included verbatim in the output.
  VisitResultPreserveHtml = Data.define do
    include VisitResult
    extend T::Sig

    sig { returns(T::Boolean) }
    def continue? = false
    sig { returns(T::Boolean) }
    def custom? = false
    sig { returns(T::Boolean) }
    def skip? = false
    sig { returns(T::Boolean) }
    def preserve_html? = true
    sig { returns(T::Boolean) }
    def error? = false
    # @param hash [Hash] deserialized from the native extension
    # @return [self]
    sig { params(hash: T::Hash[T.untyped, T.untyped]).returns(T.attached_class) }
    def self.from_hash(hash)
      new
    end
  end
  ## Stop conversion with an error
  ##
  ## The conversion process halts and returns this error message.
  VisitResultError = Data.define(:value) do
    include VisitResult
    extend T::Sig

    # @return [String]
    sig { returns(String) }
    def value = Data.instance_method(:to_h).bind_call(self).fetch(:value)
    sig { returns(T::Boolean) }
    def continue? = false
    sig { returns(T::Boolean) }
    def custom? = false
    sig { returns(T::Boolean) }
    def skip? = false
    sig { returns(T::Boolean) }
    def preserve_html? = false
    sig { returns(T::Boolean) }
    def error? = true
    # @param hash [Hash] deserialized from the native extension
    # @return [self]
    sig { params(hash: T::Hash[T.untyped, T.untyped]).returns(T.attached_class) }
    def self.from_hash(hash)
      new(value: hash[:output] || hash["output"])
    end
  end
end
